using Azurite.EditorIsolation;
using Azurite.NormalEditor.Adapter;

static class CoordinatorCases
{
    internal static void Run(string output,Action<string,Action> test,Action<bool,string> check)
    {
        Fixture New(bool admitted=true)=>new(output,admitted);
        void Denied(Fixture f,bool allowed){check(!allowed && f.Adapter.Failure is not null && f.Fatal.Calls>0,"refusal did not block original/fatal sink was skipped");}
        test("absent external admission prevents initial original and all routing",()=>{var f=New(false);Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"default denial mutated native fields");});
        test("raw Awake snapshot and post-route snapshots are recorded",()=>{var f=New();Fixture.Must(f.Adapter.AwakeEntered(100,out _));var routes=f.Admission.Routes;check(routes.Count==4 && routes[0].Before.SettingsPath=="original-before-awake" && routes[0].After is null && routes[1].After!.SettingsPath==f.Paths.Settings,"raw route history fabricated");});
        test("genuine default overwrite reroutes once before child consumption",()=>{var f=New();f.ReadChildReady();check(f.Native.Writes.Count==3 && f.Native.Settings.SettingsPath==f.Paths.Settings,"native overwrite not rerouted once");check(f.Admission.Routes[^2].Before.SettingsPath==f.Binding.ExpectedNativeSettingsPath && f.Admission.Routes[^1].After!.SettingsPath==f.Paths.Settings,"default-path raw value lost");f.ReadOriginal();});
        test("arbitrary state-zero overwritten path is not repaired",()=>{var f=New();f.BeforeYield();f.NativeYield();f.Native.Settings=f.Native.Settings with{SettingsPath="unexpected"};Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,true,true));check(f.Native.Writes.Count==2,"arbitrary drift was repaired");});
        test("later settings path drift blocks read without repair",()=>{var f=New();f.ReadChildReady();f.Native.Settings=f.Native.Settings with{SettingsPath=f.Binding.ExpectedNativeSettingsPath};Denied(f,f.Adapter.IteratorEntered(300,NativeKind.Read,out _));check(f.Native.Writes.Count==3,"late path reset silently repaired");});
        test("cached workspace drift at initial yield blocks reroute",()=>{var f=New();f.BeforeYield();f.NativeYield();f.Native.Settings=f.Native.Settings with{CachedWorkspace="other"};Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,true,true));check(f.Native.Writes.Count==2,"cached drift was repaired");});
        test("route admission denial occurs before field assignment",()=>{var f=New();f.Admission.RouteAllowed=false;Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"route denial came after write");});
        test("admission evidence cannot change between policy bind and field routing",()=>{var f=New();f.Admission.BeforeRoute=()=>f.Admission.EvidenceHash=new string('b',64);Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"changed admission evidence allowed path mutation");});
        test("route audit/admission mutation is detected before assignment",()=>{var f=New();f.Admission.BeforeRoute=()=>f.Native.Settings=f.Native.Settings with{Data=200};Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"changed raw snapshot was used");});
        test("unauthorized readiness change during setter is rejected",()=>{var f=New();f.Native.AfterWrite=()=>f.Native.Settings=f.Native.Settings with{Ready=true};Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==1,"continued routing after readiness mutation");});
        test("unauthorized data change during setter is rejected",()=>{var f=New();f.Native.AfterWrite=()=>f.Native.Settings=f.Native.Settings with{Data=200};Denied(f,f.Adapter.AwakeEntered(100,out _));});
        test("unauthorized dirty change during setter is rejected",()=>{var f=New();f.Native.AfterWrite=()=>f.Native.Settings=f.Native.Settings with{Dirty=true};Denied(f,f.Adapter.AwakeEntered(100,out _));});
        test("normal route sequence does not change data readiness dirty or iterator state",()=>{var f=New();var iter=f.Native.Iterators[250];Fixture.Must(f.Adapter.AwakeEntered(100,out _));check(f.Native.Settings.Data==0 && !f.Native.Settings.Ready && !f.Native.Settings.Dirty && f.Native.Iterators[250]==iter,"adapter changed non-route fields");});
        test("CLI active owner is rejected",()=>{var f=New();f.Native.Settings=f.Native.Settings with{CliActive=true};Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"CLI owner routed");});
        test("CLI transport is rejected",()=>{var f=New();f.Native.Settings=f.Native.Settings with{TransportPresent=true};Denied(f,f.Adapter.AwakeEntered(100,out _));});
        test("unrelated shared coroutine passes unchanged without dereference or policy event",()=>{var f=New();Fixture.Must(f.Adapter.AwakeEntered(100,out _));var count=f.Admission.Routes.Count;check(f.Adapter.CoroutineEntered(999,-999,out var frame) && frame?.Disposition==CallbackDisposition.UnrelatedShared && f.Admission.Routes.Count==count,"foreign coroutine disposition changed native/policy behavior");});
        test("bound owner unrelated coroutine is denied",()=>{var f=New();Fixture.Must(f.Adapter.AwakeEntered(100,out _));f.Native.Iterators[900]=new(900,100,NativeKind.Other,0,0);Denied(f,f.Adapter.CoroutineEntered(100,900,out _));});
        test("bound owner duplicate InitTask capture is denied",()=>{var f=New();f.BeforeYield();Denied(f,f.Adapter.CoroutineEntered(100,250,out _));});
        test("bound coroutine owner mismatch is denied",()=>{var f=New();Fixture.Must(f.Adapter.AwakeEntered(100,out _));f.Native.Iterators[250]=f.Native.Iterators[250] with{Owner=101};Denied(f,f.Adapter.CoroutineEntered(100,250,out _));});
        test("uncaptured native InitTask cannot be advanced",()=>{var f=New();Fixture.Must(f.Adapter.AwakeEntered(100,out _));Denied(f,f.Adapter.IteratorEntered(250,NativeKind.Init,out _));});
        test("wrong yielded read child class is denied before reroute",()=>{var f=New();f.BeforeYield();f.NativeYield();f.Native.Iterators[300]=f.Native.Iterators[300] with{Kind=NativeKind.Save};Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,true,true));check(f.Native.Writes.Count==2,"wrong child allowed reroute");});
        test("wrong yielded read child owner is denied before reroute",()=>{var f=New();f.BeforeYield();f.NativeYield();f.Native.Iterators[300]=f.Native.Iterators[300] with{Owner=101};Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,true,true));});
        test("foreign return token is denied",()=>{var a=New();var b=New();a.BeforeYield();b.BeforeYield();Denied(b,b.Adapter.Returned(a.InitFrame,CallbackKind.Init,250,true,true));});
        test("out-of-order return cannot bypass nested original",()=>{var f=New();f.BeforeYield();Denied(f,f.Adapter.Returned(f.AwakeFrame,CallbackKind.Awake,100,true));});
        test("skipped original cannot be reported as successful yield",()=>{var f=New();f.BeforeYield();f.NativeYield();Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,false,true));check(f.Native.Writes.Count==2,"skipped native body routed");});
        test("exceptional original latches failure even when fatal sink returns",()=>{var f=New();f.BeforeYield();var original=new InvalidOperationException("fixture original exception");check(ReferenceEquals(FinalizerDispatch.Complete(f.Adapter,CallbackKind.Init,250,f.InitFrame,original),original),"original exception changed");check(f.Adapter.Failure is not null && f.Fatal.Calls>0,"exception finalizer did not refuse");Denied(f,f.Adapter.IteratorEntered(300,NativeKind.Read,out _));});
        test("missing original return is caught by finalization",()=>{var f=New();f.BeforeYield();FinalizerDispatch.Complete(f.Adapter,CallbackKind.Init,250,f.InitFrame,null);check(f.Adapter.Failure is not null && f.Fatal.Calls>0,"missing original return was finalized");});
        test("duplicate original return is denied",()=>{var f=New();f.ReadChildReady();Denied(f,f.Adapter.Returned(f.InitFrame,CallbackKind.Init,250,true,true));});
        test("read child cannot run before yielded return reroute",()=>{var f=New();f.BeforeYield();Denied(f,f.Adapter.IteratorEntered(300,NativeKind.Read,out _));});
        test("read fallback initialization is denied",()=>{var f=New();f.ReadChildReady();Denied(f,f.Adapter.RejectFallback());check(!f.Adapter.Policy.InitializationCompleted,"fallback completed startup");});
        test("read result marker is observed rather than fabricated",()=>{var f=New();f.ReadChildReady();Fixture.Must(f.Adapter.IteratorEntered(300,NativeKind.Read,out var frame));f.Native.Iterators[300]=f.Native.Iterators[300] with{State=-1};f.Native.Settings=f.Native.Settings with{Data=200,DataWorkspace=f.Paths.Workspace,DataCache=f.Paths.Cache,Marker="wrong"};Denied(f,f.Adapter.Returned(frame,CallbackKind.Read,300,true,false));});
        test("external resource denial prevents actual resource original",()=>{var f=New();f.Continue(false);f.Admission.ResourceAllowed=false;Denied(f,f.Adapter.ResourceEntered(500,out _));check(f.Adapter.Policy.ResourceStartObservations==0,"denied resource counted");});
        test("false-ready resource observation occurs inside original continuation",()=>{var f=New();f.Continue();check(f.Adapter.Policy.ResourceStartObservations==1 && !f.Adapter.Policy.ReadyObserved,"resource origin fabricated readiness");});
        test("later direct-ready resource path remains representable",()=>{var f=New();f.Start(false);Fixture.Must(f.Adapter.ResourceEntered(500,out var r));f.Return(r,CallbackKind.Resource,500,true);check(f.Adapter.Policy.ResourceStartObservations==1,"late resource failed");});
        test("early false-ready resource without continuation is denied",()=>{var f=New();f.ReadChildReady();f.ReadOriginal();Denied(f,f.Adapter.ResourceEntered(500,out _));});
        test("natural saver initial wait nests before InitTask original return",()=>{var f=New();f.Continue();f.CaptureSaver();f.InitialWait();check(!f.Adapter.Policy.InitializationCompleted && f.Adapter.Policy.CompletedSaveResumes==0,"initial wait completed outer InitTask");f.Complete();check(f.Adapter.Policy.InitializationCompleted,"terminal original return missing");});
        test("initial saver can run after original InitTask returns",()=>{var f=New();f.Continue();f.CaptureSaver();f.Complete();f.InitialWait();f.Save("1");check(f.Adapter.Policy.CompletedWrites==1,"late initial wait rejected");});
        test("state-one saver before InitTask completion is denied",()=>{var f=New();f.Continue();f.CaptureSaver();f.InitialWait();Denied(f,f.Adapter.IteratorEntered(400,NativeKind.Save,out _));});
        test("saver initial wait reentrancy is denied",()=>{var f=New();f.Continue();f.CaptureSaver();Fixture.Must(f.Adapter.IteratorEntered(400,NativeKind.Save,out _));Denied(f,f.Adapter.IteratorEntered(400,NativeKind.Save,out _));});
        test("bound saver cannot be captured outside continuation",()=>{var f=New();f.ReadChildReady();f.ReadOriginal();f.Native.Settings=f.Native.Settings with{Ready=true};Denied(f,f.Adapter.CoroutineEntered(100,400,out _));});
        test("two dirty and two clean native-shaped cycles preserve late counters",()=>{var f=New();f.Start();f.Save("1");f.Save("unused",false);f.Save("2");f.Save("unused",false);check(f.Adapter.Policy.CompletedWrites==2 && f.Adapter.Policy.CompletedSaveResumes==4 && f.Adapter.Policy.RepeatedSaveLineageObserved,"cycle lineage failed");check(f.Native.Writes.Count==3,"save cycle changed routing fields");});
        test("identical-content cycles retain lineage",()=>{var f=New();f.Start();f.Save("same");f.Save("same");check(f.Adapter.Policy.RepeatedSaveLineageObserved,"identical original writes rejected");});
        test("write lacks permission without a real save frame",()=>{var f=New();f.Start();Denied(f,f.Adapter.WriteEntered(100,out _));});
        test("foreign settings writer is refused rather than treated as foreign shared traffic",()=>{var f=New();f.Start();Denied(f,f.Adapter.WriteEntered(101,out _));});
        test("foreign settings iterator owner is refused at its dedicated callback",()=>{var f=New();f.Start();f.Native.Iterators[900]=new(900,101,NativeKind.Read,0,0);Denied(f,f.Adapter.IteratorEntered(900,NativeKind.Read,out _));});
        test("missing bound original-return token latches refusal",()=>{var f=New();f.BeforeYield();Denied(f,f.Adapter.Returned(null,CallbackKind.Init,250,true,true));});
        test("write count waits for original enclosing saver return",()=>{var f=New();f.Start();f.Native.Settings=f.Native.Settings with{Dirty=true};Fixture.Must(f.Adapter.IteratorEntered(400,NativeKind.Save,out var s));Fixture.Must(f.Adapter.WriteEntered(100,out var w));f.SaveFiles("1");f.Return(w,CallbackKind.Write,100,true);check(f.Adapter.Policy.CompletedWrites==0,"write counted before saver returned");f.Return(s,CallbackKind.Save,400,true,true);check(f.Adapter.Policy.CompletedWrites==1,"valid saver not committed");});
        test("fresh drift after write return is refused at cycle commit",()=>{var f=New();f.Start();f.Native.Settings=f.Native.Settings with{Dirty=true};Fixture.Must(f.Adapter.IteratorEntered(400,NativeKind.Save,out var s));Fixture.Must(f.Adapter.WriteEntered(100,out var w));f.SaveFiles("1");f.Return(w,CallbackKind.Write,100,true);File.WriteAllText(f.Paths.Settings+".bk.1","changed");Denied(f,f.Adapter.Returned(s,CallbackKind.Save,400,true,true));check(f.Adapter.Policy.CompletedWrites==0,"refusal counted");});
        test("revoked admission stops original save prefix",()=>{var f=New();f.Start();f.Admission.Revoked=true;Denied(f,f.Adapter.IteratorEntered(400,NativeKind.Save,out _));});
        test("observed native thread drift is denied",()=>{var f=New();f.Start();f.Native.NativeThreadId=99;Denied(f,f.Adapter.IteratorEntered(400,NativeKind.Save,out _));});
        test("actual managed thread drift is denied",()=>{var f=New();f.Start();var allowed=Task.Run(()=>f.Adapter.IteratorEntered(400,NativeKind.Save,out _)).GetAwaiter().GetResult();Denied(f,allowed);});
        test("nested route callback refusal cannot be swallowed",()=>{var f=New();f.Admission.BeforeRoute=()=>f.Adapter.RejectFallback();Denied(f,f.Adapter.AwakeEntered(100,out _));check(f.Native.Writes.Count==0,"swallowed nested refusal allowed routing");});
        test("ready flag regression stops subsequent original",()=>{var f=New();f.Start();f.Native.Settings=f.Native.Settings with{Ready=false};Denied(f,f.Adapter.IteratorEntered(400,NativeKind.Save,out _));});
        test("both shared aliases must be unowned before registration",()=>{foreach(var owners in new[]{(new[]{"foreign"},Array.Empty<string>()),(Array.Empty<string>(),new[]{"foreign"})}){bool denied=false;try{InstallationAuthority.RequireUnownedAliases(owners.Item1,owners.Item2);}catch(InvalidOperationException){denied=true;}check(denied,"alias ownership conflict ignored");}});
        test("unowned shared aliases pass pure installation prerequisite",()=>InstallationAuthority.RequireUnownedAliases(Array.Empty<string>(),Array.Empty<string>()));
        test("arbitrary contained lab is not the approved normal installation",()=>{var f=New();bool denied=false;try{InstallationAuthority.Require(f.Binding,Path.Combine(f.Paths.Install,"AzureArchive.exe"),Path.Combine(f.Paths.Install,InstallationAuthority.AdapterSubdirectory,"Azurite.NormalEditor.Adapter.Host.PreparationOnly.dll"));}catch(InvalidOperationException){denied=true;}check(denied,"containment was mistaken for authority");});
        test("approved normal lab identity is checked without filesystem access",()=>{var f=New();var lab=InstallationAuthority.ApprovedLabRoot;var paths=new RunPaths(lab,Path.Combine(lab,"runs",f.Binding.Policy.RunId),Path.Combine(lab,"install"));var b=f.Binding with{Policy=f.Binding.Policy with{Paths=paths}};InstallationAuthority.Require(b,Path.Combine(paths.Install,"AzureArchive.exe"),Path.Combine(paths.Install,InstallationAuthority.AdapterSubdirectory,"Azurite.NormalEditor.Adapter.Host.PreparationOnly.dll"));});
        test("missing outer return blocks close",()=>{var f=New();f.BeforeYield();Denied(f,f.Adapter.Close());});
        test("quiescent completed lifecycle can close",()=>{var f=New();f.Start();Fixture.Must(f.Adapter.Close());});
    }
}
